text:
/* SilbaÄtno repertoire homepage — scoped, responsive and independent from Forge theme. */
.tc-tiddler-frame[data-tiddler-title="SilbaÄtno Repertoire – Oversigt"] .tc-tiddler-title .tc-title {display:none;}
.silba-home {font-family:inherit;color:#243547;line-height:1.55;max-width:1100px;margin:0 auto;}
.silba-home * {box-sizing:border-box;}
.silba-hero {display:grid;grid-template-columns:minmax(0,1fr) minmax(255px,.82fr);gap:0;background:#142c40;border-radius:19px;overflow:hidden;box-shadow:0 12px 35px rgba(16,36,53,.17);}
.silba-hero-copy {padding:clamp(28px,5vw,56px);display:flex;flex-direction:column;justify-content:center;color:#fff;}
.silba-eyebrow {margin:0 0 15px!important;font-size:.77rem;letter-spacing:.14em;font-weight:750;color:#f0cb80;}
.silba-hero h1 {font-size:clamp(2.8rem,6vw,4.9rem)!important;line-height:1.04;letter-spacing:-.05em;color:#fff!important;margin:0 0 6px!important;}
.silba-hero-subtitle {font-size:clamp(1.35rem,2.2vw,1.65rem);font-weight:520;margin:0 0 16px!important;color:#e6e4d5;}
.silba-lead {font-size:1rem;max-width:42ch;color:#e0e9ef;margin:0 0 24px!important;}
.silba-actions {display:flex;gap:10px;flex-wrap:wrap;margin-bottom:12px;}
.silba-actions a {display:inline-flex;align-items:center;justify-content:center;border-radius:9px;padding:12px 18px;text-decoration:none!important;font-size:1rem;font-weight:750;line-height:1.25;}
.silba-primary,.silba-primary:visited {background:#ecd18f;color:#152c3b!important;}
.silba-secondary,.silba-secondary:visited {background:transparent;color:#fff!important;border:1px solid #b5cad5;}
.silba-primary:hover {background:#ffe0a0;}
.silba-secondary:hover {background:#ffffff22;}
.silba-hero-hint {font-size:.83rem;color:#c6d7e0;margin:0!important;line-height:1.4;}
.silba-hero-photo {position:relative;min-height:310px;margin:0!important;background:radial-gradient(circle at 70% 30%,#527486,#203f50 65%);}
.silba-photo-visual {width:100%;height:100%;min-height:310px;display:block;background-image:linear-gradient(155deg,rgba(10,31,46,.08),rgba(10,31,46,.36)),url("https://akustisk-elektrisk.dk/gif/silbaaetno-2026.jpg"),radial-gradient(circle at 75% 25%,#6d968e,#1c3d50 68%);background-position:center;background-size:cover;}
.silba-hero-photo figcaption {position:absolute;left:0;right:0;bottom:0;padding:13px 16px;color:#fff;background:linear-gradient(transparent,#0009);font-size:.75rem;}
.silba-hero-photo a,.silba-hero-photo a:visited {color:#fff;text-decoration:underline;}
.silba-metrics {display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:20px 0 28px;}
.silba-metrics>div {padding:17px 20px;border:1px solid #dfe9e8;border-radius:12px;background:#f5f9f7;}
.silba-metrics strong {display:block;font-size:2rem;font-weight:770;line-height:1.1;color:#176b66;}
.silba-metrics span {display:block;font-size:.89rem;color:#556a77;margin-top:4px;}
.silba-intro {padding:0 2px;margin-bottom:22px;}
.silba-home h2 {font-size:clamp(1.28rem,2vw,1.6rem)!important;line-height:1.23;font-weight:720;color:#1c3b4d;margin:0 0 10px!important;}
.silba-intro p {max-width:78ch;color:#49606c;margin:0!important;}
.silba-section {background:#fff;border:1px solid #dce6e5;border-radius:15px;padding:clamp(18px,2.8vw,29px);box-shadow:0 5px 16px rgba(19,44,55,.05);}
.silba-section-heading {display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;padding-bottom:13px;border-bottom:1px solid #e8efef;margin-bottom:10px;}
.silba-section-heading h2 {margin:0!important;}
.silba-section-heading>span {font-size:.82rem;color:#647d83;border-radius:30px;background:#edf3f1;padding:5px 11px;}
.silba-track-list {list-style:none!important;margin:0!important;padding:0!important;display:grid;grid-template-columns:minmax(0,1fr);gap:6px;counter-reset:none;}
.silba-track-list li {display:flex;align-items:center;gap:11px;padding:13px 3px;border-bottom:1px solid #edf1f1;min-width:0;margin:0!important;}
.silba-track-list li a {font-size:.95rem;font-weight:630;flex:1;min-width:0;overflow-wrap:anywhere;color:#175e6c;text-decoration:none;}
.silba-track-list li a:hover {text-decoration:underline;}
.silba-index {display:inline-flex;flex:0 0 30px;width:30px;height:30px;border-radius:8px;background:#f3e9cf;color:#68562c;font-size:.78rem;font-weight:760;align-items:center;justify-content:center;}
.silba-track-meta {font-size:.72rem;color:#83999c;white-space:nowrap;}
.silba-secondary-grid {display:grid;grid-template-columns:1fr 1fr;gap:15px;margin-top:15px;}
.silba-secondary-grid .silba-track-list {grid-template-columns:1fr;}
.silba-secondary-grid p {font-size:.9rem;color:#657980;margin:4px 0 9px!important;}
.silba-note {background:#f7f9f7;border-left:4px solid #bd9c50;padding:20px 22px;margin-top:18px;border-radius:0 12px 12px 0;}
.silba-note h2 {font-size:1.1rem!important;}
.silba-note p {font-size:.92rem;color:#526772;margin:7px 0!important;}
.silba-note a {font-weight:680;}
@media(max-width:1020px) {.silba-track-meta {display:none;}}
@media(max-width:750px) {
 .silba-hero {grid-template-columns:1fr;}
 .silba-hero-copy {padding:28px;}
 .silba-hero-photo {min-height:190px;max-height:260px;}
 .silba-photo-visual {min-height:190px;max-height:260px;}
 .silba-track-list,.silba-secondary-grid {grid-template-columns:1fr;}
 .silba-metrics {gap:8px;}
 .silba-metrics>div {padding:12px;}
 .silba-metrics strong {font-size:1.65rem;}
 .silba-metrics span {font-size:.76rem;}
}
@media(max-width:380px) {.silba-metrics {grid-template-columns:1fr;} }
